import{_ as t,o as a,c as o,a6 as i,a8 as r,a9 as s,aa as n,ab as l,ac as d,ad as c,ae as h,af as m}from"./chunks/framework.G3KnGQmO.js";const w=JSON.parse('{"title":"Document Repository","description":"","frontmatter":{},"headers":[],"relativePath":"content/plugins/bcew-document-repository/bcew-document-repository-feature.md","filePath":"content/plugins/bcew-document-repository/bcew-document-repository-feature.md"}'),u={name:"content/plugins/bcew-document-repository/bcew-document-repository-feature.md"};function p(g,e,f,b,y,v){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="document-repository" tabindex="-1">Document Repository <a class="header-anchor" href="#document-repository" aria-label="Permalink to “Document Repository”">​</a></h1><p>The Document Repository lets administrators and authorized users upload, organize, search, and manage PDF documents on a WordPress site. Documents are stored separately from regular posts and can be enriched with custom metadata fields for better searchability and organization.</p><p><img src="'+r+'" alt="Document Repository Overview"></p><hr><h2 id="prerequisites-access" tabindex="-1">Prerequisites &amp; access <a class="header-anchor" href="#prerequisites-access" aria-label="Permalink to “Prerequisites &amp; access”">​</a></h2><ul><li>Document Repository plugin installed and enabled.</li><li>WordPress Search plugin installed and enabled (to search document metadata).</li><li>Admins or users with edit capability can upload, edit, and delete documents.</li></ul><hr><h2 id="where-to-find-it" tabindex="-1">Where to find it <a class="header-anchor" href="#where-to-find-it" aria-label="Permalink to “Where to find it”">​</a></h2><p>In WordPress Admin: <strong>Document Repository</strong> (left navigation).</p><p><img src="'+s+'" alt="Where To Find Document Repository"></p><hr><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to “What you can do”">​</a></h2><ul><li>Upload PDF documents (PDF format only).</li><li>Organize documents with titles and excerpts.</li><li>Add metadata via custom fields defined in <strong>Metadata Settings</strong>.</li><li>Search and filter by document content and metadata.</li><li>View documents in two modes: standard list and spreadsheet.</li><li>Manage permissions to control access.</li></ul><hr><h2 id="upload-a-document" tabindex="-1">Upload a document <a class="header-anchor" href="#upload-a-document" aria-label="Permalink to “Upload a document”">​</a></h2><ol><li>Go to <strong>Document Repository</strong> in WordPress Admin.</li><li>Drag one or more files into the <strong>Drag &amp; Drop</strong> area, or click <strong>Choose Files</strong>.</li><li>Select a PDF on your computer and click <strong>Open</strong>.</li><li>After upload, the document appears in the list.</li></ol><p>Note: Only valid PDF files are accepted. Non‑PDF files are rejected.</p><p><img src="'+n+'" alt="Upload a Document"></p><hr><h2 id="edit-document-metadata" tabindex="-1">Edit document metadata <a class="header-anchor" href="#edit-document-metadata" aria-label="Permalink to “Edit document metadata”">​</a></h2><ol><li>Go to <strong>Document Repository</strong>.</li><li>Click the pencil icon to open the metadata editor. In <strong>Spreadsheet Mode</strong>, edit fields inline.</li><li>Update the <strong>Title</strong>, <strong>Excerpt</strong>, and <strong>Metadata Fields</strong>, if any exist.</li><li>Click <strong>Save Changes</strong>. Edits apply immediately and are reflected in the list.</li></ol><blockquote><p>Note: Taxonomy fields may contain one or more values, separated by commas or Enter key</p></blockquote><p><img src="'+l+'" alt="Edit a Document"></p><hr><h2 id="delete-trash-a-document" tabindex="-1">Delete (trash) a document <a class="header-anchor" href="#delete-trash-a-document" aria-label="Permalink to “Delete (trash) a document”">​</a></h2><ol><li>Go to <strong>Document Repository</strong>.</li><li>Select one or more documents and click <strong>Trash Selected</strong>, or click the <strong>Trash</strong> icon in the Actions column.</li><li>Review the confirmation message.</li><li>Click <strong>Trash</strong> (or <strong>Trash Selected</strong>) to confirm, or <strong>Cancel</strong> to abort.</li></ol><p>Effect:</p><ul><li>The document is moved to <strong>Trash</strong>.</li><li>From the <strong>Trash</strong> view, you can <strong>Restore</strong> or <strong>Delete Permanently</strong>.</li><li>When permanently deleted, the file is removed from the server and all associated metadata is deleted.</li></ul><p><img src="'+d+'" alt="Delete a Document"></p><hr><h2 id="search-documents" tabindex="-1">Search documents <a class="header-anchor" href="#search-documents" aria-label="Permalink to “Search documents”">​</a></h2><h3 id="keyword-search" tabindex="-1">Keyword search <a class="header-anchor" href="#keyword-search" aria-label="Permalink to “Keyword search”">​</a></h3><ol><li>Use the <strong>Search</strong> box at the top of the Document Repository.</li><li>Enter a keyword. It matches titles, excerpts, and all metadata fields.</li><li>Press <strong>Enter</strong> or click <strong>Search</strong>.</li><li>To reset, clear the input and press <strong>Enter</strong>, or click the <strong>X</strong> button.</li></ol><p>Results include documents whose title, excerpt, or metadata matches your term.</p><p><img src="'+c+'" alt="Search For Documents in the repository"></p><hr><h2 id="view-modes" tabindex="-1">View modes <a class="header-anchor" href="#view-modes" aria-label="Permalink to “View modes”">​</a></h2><h3 id="standard-view-default" tabindex="-1">Standard view (default) <a class="header-anchor" href="#standard-view-default" aria-label="Permalink to “Standard view (default)”">​</a></h3><p>Shows:</p><ul><li>Title and excerpt</li><li>Metadata columns (if configured)</li><li>File size and type (PDF)</li><li>Revisions</li><li>Action buttons (Download, Edit Metadata, Trash)</li></ul><p>Best for browsing and managing a moderate number of documents.</p><h3 id="spreadsheet-view" tabindex="-1">Spreadsheet view <a class="header-anchor" href="#spreadsheet-view" aria-label="Permalink to “Spreadsheet view”">​</a></h3><p>Shows:</p><ul><li>All documents and metadata in columns</li><li>Inline editing for quick updates</li><li>Ideal for bulk edits and comparisons</li></ul><p>To switch views, use the <strong>View Mode</strong> toggle in the top‑right.</p><p><img src="'+h+'" alt="Switch View Modes"></p><hr><h2 id="document-revisions" tabindex="-1">Document revisions <a class="header-anchor" href="#document-revisions" aria-label="Permalink to “Document revisions”">​</a></h2><p>Revisions track changes made to the document’s content fields (including Excerpt). You can view previous versions and restore one if needed.</p><ol><li>Click <strong>Revisions</strong> for a document.</li><li>Use <strong>Previous</strong> and <strong>Next</strong> to navigate versions.</li><li>Click <strong>Restore this Revision</strong> to apply it; this opens the editor.</li><li>Optionally click <strong>Edit Revision</strong> to adjust the revision text and click <strong>Save</strong>.</li><li>Return to <strong>Document Repository</strong> to see your changes.</li></ol><p><img src="'+m+'" alt="Document Revisions"></p><hr><h2 id="document-status" tabindex="-1">Document status <a class="header-anchor" href="#document-status" aria-label="Permalink to “Document status”">​</a></h2><p>Documents can be:</p><ul><li><strong>Published</strong>: Visible on the site (frontend and admin).</li><li><strong>Draft</strong>: Saved but not yet published.</li><li><strong>Pending Review</strong>: Submitted for review; an Editor can publish it.</li></ul><p>To restore a trashed document: go to <strong>Document Repository</strong>, open <strong>Trash</strong>, select the document, and click <strong>Restore</strong>.</p><hr><h2 id="tips-best-practices" tabindex="-1">Tips &amp; best practices <a class="header-anchor" href="#tips-best-practices" aria-label="Permalink to “Tips &amp; best practices”">​</a></h2><ul><li>Use descriptive titles and excerpts to improve search results.</li><li>Define metadata fields in <strong>Metadata Settings</strong> before large uploads.</li><li>Ensure files are valid PDFs before uploading.</li><li>Review and remove outdated documents regularly.</li><li>Use search and filters to verify correct metadata tagging.</li><li>For large repositories (100+ documents), use <strong>Spreadsheet View</strong> for faster bulk edits.</li></ul><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><ul><li>Upload rejected as “Not a PDF”: Confirm the file is a valid PDF and has a .pdf extension. Convert non‑PDF files to PDF before uploading.</li><li>Upload fails: Check hosting file size limits. Try a smaller PDF or split large files.</li><li>Document not found in search: Ensure the WordPress Search plugin is installed and activated to index metadata.</li><li>Metadata fields missing: Create fields in <strong>Metadata Settings</strong>, then refresh the page.</li><li>Cannot edit or delete: Verify your user role has edit capability.</li><li>File appears corrupted: Re‑upload the PDF. If it persists, open and re‑save the file in your PDF app, then upload again.</li></ul><hr><h2 id="quick-reference" tabindex="-1">Quick reference <a class="header-anchor" href="#quick-reference" aria-label="Permalink to “Quick reference”">​</a></h2><ul><li>Location: <strong>Document Repository</strong> (left navigation)</li><li>Format: PDF only</li><li>Upload: Drag &amp; drop or click <strong>Choose Files</strong></li><li>Edit: Click <strong>Edit</strong>, change fields, click <strong>Save Changes</strong></li><li>Delete: Click <strong>Trash</strong> or <strong>Trash Selected</strong>; restore or permanently delete from <strong>Trash</strong></li><li>Search: Use the <strong>Search</strong> box</li><li>View modes: Toggle between <strong>Standard</strong> and <strong>Spreadsheet</strong></li><li>Who can manage: Admins or users with edit capability</li></ul>',65)])])}const k=t(u,[["render",p]]);export{w as __pageData,k as default};
